const test = require("node:test");
const assert = require("node:assert");

const { Processor } = require("./processor");

test("duplicate key within window is not re-executed", () => {
  const p = new Processor(10);
  const first = p.process("order-1", { amount: 5 }, 0);
  const second = p.process("order-1", { amount: 999 }, 5);
  assert.deepStrictEqual(second, first);
  assert.strictEqual(p.effects.length, 1);
});

test("different keys both execute", () => {
  const p = new Processor(10);
  p.process("a", 1, 0);
  p.process("b", 2, 0);
  assert.strictEqual(p.effects.length, 2);
});

test("re-executes after window expires", () => {
  const p = new Processor(10);
  p.process("order-1", { amount: 5 }, 0);
  p.process("order-1", { amount: 5 }, 9);
  assert.strictEqual(p.effects.length, 1);
  p.process("order-1", { amount: 7 }, 10);
  assert.strictEqual(p.effects.length, 2);
  assert.deepStrictEqual(p.effects[1], ["order-1", { amount: 7 }]);
});

