class Processor {
  constructor(window) {
    this.window = window;
    this.effects = [];
    this.seen = new Map(); // key -> [result, recordedAt]
  }

  process(key, payload, now) {
    const cached = this.seen.get(key);
    if (cached !== undefined) {
      const [result, recordedAt] = cached;
      if (now - recordedAt < this.window) {
        return result;
      }
    }
    this.effects.push([key, payload]);
    const result = { key, payload, processedAt: now };
    this.seen.set(key, [result, now]);
    return result;
  }
}

module.exports = { Processor };

