class Processor {
  constructor(window) {
    this.window = window;
    this.effects = [];
    this.seen = new Map(); // key -> result
  }

  process(key, payload, now) {
    if (this.seen.has(key)) {
      return this.seen.get(key);
    }
    this.effects.push([key, payload]);
    const result = { key, payload, processedAt: now };
    this.seen.set(key, result);
    return result;
  }
}

module.exports = { Processor };
